c=org.jsoup.Jsoup.parse(qbl).select(".sortChannel_nav a");
push("🌹分类🌹",null,1)
    for(i in a){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
  url=String(url).replace(/(.*)/,"$1<,{{page}}.html>")
        push(title,url,size)
    };
 push("🌹排行🌹",null,1)
    for(i in b){
        title=b[i].text()
        url=b[i].attr("href")
  url=String(url).replace(/(.*)/,"$1<,{{page}}.html>")
        size=0.25;
        push(title,url,size)
    }

   push("🌹全本🌹",null,1)
    for(i in c){
